106	%% 3. METHOD
107	%% ============================================================
108	\section{Method}
109	
110	\subsection{Problem Formulation}
111	
112	Let $\theta_j$ denote the true (uncontaminated) ability of model $j$ on a benchmark, $e_{ij}\in[0,1]$ the contamination exposure score for item $i$ and model $j$, and $\gamma_k > 0$ the contamination susceptibility of benchmark $k$.
113	We seek a calibrated score $\hat{\theta}_j$ such that the counterfactual accuracy (at $e_{ij}=0$ for all $i$) approximates $\theta_j$.
114	
115	\subsection{Stage 1: Per-Item Exposure Mapping}
116	
117	We compute four detection signals for each item--model pair:
118	\begin{itemize}
119	\item \textbf{S1 (Embedding Retrieval):} Cosine similarity between the test item and the nearest training-set item in sentence-transformer embedding space. Scale-invariant (AUC$\geq$0.95 across all model sizes).
120	\item \textbf{S2 (Min-K\%++):} Token-level perplexity anomaly detection \citep{shi2024detecting}. Scale-dependent: AUC$\approx$0.47 at 0.5B, $\geq$0.72 at $\geq$1.5B.
121	\item \textbf{S3 (ConStat):} Performance gap between original and paraphrased items \citep{dekoninck2024constat}. Available without logit access.
122	\item \textbf{S4 (Self-Critique):} Entropy collapse on familiar items \citep{weller2024selfcritique}. Scale-dependent with threshold at ${\sim}1.4$B.
123	\end{itemize}
124	
125	Signals are aggregated via Reciprocal Rank Fusion (RRF; \citealt{cormack2009reciprocal}):
126	\begin{equation}
127	\text{RRF}(i) = \sum_{s=1}^{S} \frac{1}{k + r_s(i)}
128	\end{equation}
129	where $r_s(i)$ is the rank of item $i$ under signal $s$ and $k=60$ is the standard smoothing constant.
130	RRF is training-free, avoiding meta-circularity: a learned aggregator's training data may itself be contaminated.
131	When constituent signals fail (e.g., S2/S4 at 0.5B), RRF gracefully degrades to the dominant signal.
132	
133	\subsection{Stage 2: Contamination-Augmented 4PL IRT}
134	
135	We augment the standard four-parameter logistic IRT model \citep{deboeck2004explanatory} with a contamination term.
136	The probability of model $j$ answering item $i$ correctly on benchmark $k$ is:
137	\begin{equation}
138	P(Y_{ij}=1) = c_i + \frac{d_i - c_i}{1 + \exp\!\bigl(-a_i(\theta_j - b_i + \gamma_k \cdot e_{ij})\bigr)}
139	\end{equation}
140	where $a_i$ is item discrimination, $b_i$ item difficulty, $c_i$ the guessing parameter, $d_i$ the upper asymptote, $\theta_j$ model ability, $\gamma_k$ per-benchmark contamination susceptibility, and $e_{ij}$ the exposure score from Stage~1.
141	
142	The counterfactual (calibrated) score for model $j$ is:
143	\begin{equation}
144	\hat{\theta}_j^{\text{cal}} = \frac{1}{N_k}\sum_{i=1}^{N_k} P(Y_{ij}=1 \given e_{ij}=0, \hat{\theta}_j, \hat{a}_i, \hat{b}_i, \hat{c}_i, \hat{d}_i)
145	\end{equation}
146	
147	\paragraph{Measurement Error Model.}
148	Exposure scores $e_{ij}$ are noisy estimates of latent true exposure $\tau_{ij}$.
149	We model $e_{ij} = \tau_{ij} + \epsilon_{ij}$ where $\epsilon_{ij} \sim \mathcal{N}(0, \sigma^2_e)$ and propagate this uncertainty through the posterior via a measurement error (ME) model \citep{carroll2006measurement}.
150	Models with high-AUC signals receive tighter credible intervals; those with degraded signals receive appropriately wider intervals.
151	
152	\paragraph{Priors and Inference.}
153	We fit per-benchmark models using Stan NUTS \citep{carpenter2017stan} with weakly informative priors: $a_i \sim \text{LogNormal}(0, 0.5)$, $b_i \sim \mathcal{N}(0, 1)$, $c_i \sim \text{Beta}(2, 8)$, $d_i \sim \text{Beta}(8, 2)$, $\theta_j \sim \mathcal{N}(0, 1)$, $\gamma_k \sim \text{HalfNormal}(0, 1)$.
154	Models are pooled across scales and seeds ($N_{\text{models}} = 32$).
155	Convergence is verified by $\hat{R} < 1.01$ and ESS $> 380$ for all parameters.
156	
157	\paragraph{Identifiability Analysis.}
158	Fisher Information for $\gamma_k$ depends on signal quality (via $e_{ij}$ variance) and sample size.
159	We define a \emph{structural threshold} (AUC$\geq$0.55: $\gamma$ is technically identifiable) and a \emph{practical threshold} (AUC$\geq$0.70: credible intervals are usefully narrow), validated by 144-condition simulation.
160	
161	\paragraph{Local Independence.}
162	Standard IRT assumes independent examinees; a single LLM produces all responses, inducing correlation through shared parameters \citep{mislevy1986bayes}.
163	We mitigate by (1)~fitting per-benchmark (reducing correlation scope), (2)~pooling models across scales and seeds, and (3)~reporting SBC diagnostics \citep{talts2020validating} to verify model specification.
164	
